    title.value = "Draft title"; description.value = "Draft description";
    button(modal, "Add tasks").click(); await settle(); const picker = window.lastModal;
    picker.inputEl.value = "task"; picker.inputEl.dispatchEvent(new Event("input")); picker.inputEl.focus(); picker.resultContainerEl.scrollTop = 20;
    const search = picker.inputEl.value; omit = "timed"; await invalidate();
    check(modal.phaseRead.selected.has("timed") && modal.contentEl.textContent.includes("Timed"), "Missing selected assignment stays represented");
    check(picker.inputEl.value === search && document.activeElement === picker.inputEl, "Picker text/focus survive task invalidation");
    check(title.value === "Draft title" && description.value === "Draft description", "Title and description drafts survive refresh"); picker.close();
    check(modal.contentEl.querySelector('[data-phase-unavailable]'), "Unavailable selected row has restrained feedback");
    fail = true; await invalidate(); check(modal.phaseRead.selected.has("timed") && modal.contentEl.textContent.includes("temporarily unavailable"), "Failed query preserves selection and status");
    fail = false; omit = null; await invalidate(); check(!modal.contentEl.querySelector('[data-phase-unavailable]'), "Recovery restores selected source availability");
