    contents.set(hubPath, "# Hub\n- [ ] Early candidate <!-- hub-task:early-candidate -->\n"); ctx.index(files.get(hubPath));
    delayed = true; await invalidate(); await gate(); typing.inputEl.value = "app"; typing.inputEl.dispatchEvent(new Event("input"));
    typing.inputEl.dispatchEvent(new KeyboardEvent("keydown", { key: "ArrowDown", bubbles: true }));
    const expected = typing.getSuggestions(typing.inputEl.value)[typing.index].item.hubTaskId;
    const scroll = typing.resultContainerEl.scrollTop; gates.splice(0).forEach(resolve => resolve()); delayed = false; await settle();
    check(typing.getSuggestions(typing.inputEl.value)[typing.index].item.hubTaskId === expected && typing.inputEl.value === "app", "Typing and keyboard selection during pending read retain the same task identity");
    check(typing.resultContainerEl.scrollTop === scroll, "Picker scroll survives candidate refresh"); typing.close();
