    button(modal, "Remove").focus(); const focused = document.activeElement; await invalidate(); check(document.activeElement === focused, "Unchanged selected row retains Remove focus");
    modal.close(); check(JSON.stringify(plugin.projectWizard.data) === beforeState && JSON.stringify([...contents]) === beforeNotes, "Cancel after reads/typing never writes planning or task state");
    modal = open(); await modal.ready; const removedId = [...modal.phaseRead.selected.keys()][0];
    button(modal, "Remove").focus(); button(modal, "Remove").click();
    check(document.activeElement === button(modal, "Remove") || document.activeElement === button(modal, "Add tasks"), "Keyboard Remove restores row or Add focus");
    await invalidate(); check(!modal.phaseRead.selected.has(removedId) && modal.phaseRead.removals.has(removedId), "Explicit Remove survives refresh");
