    modal = open(); await modal.ready; button(modal, "Add tasks").click(); await settle();
    const choosing = window.lastModal, candidate = choosing.getItems().find(task => task.hubTaskId === "unscheduled");
    choosing.inputEl.value = "Unscheduled"; choosing.inputEl.dispatchEvent(new Event("input")); choosing.inputEl.dispatchEvent(new KeyboardEvent("keydown", { key: "Enter", bubbles: true }));
    check(modal.phaseRead.selected.has("unscheduled"), "Native picker selection callback preserves identity");
    const source = candidate.path, original = contents.get(source); contents.set(source, original.replace("Unscheduled", "Changed source"));
    button(modal, "Save").click(); await settle(); check(!modal.closed && modal.phaseRead.additions.has("unscheduled") && modal.contentEl.querySelector('[role="alert"]').textContent, "Stale source save fails and retains modal/draft");
    contents.set(source, original); modal.close();
    // A pending query may not mutate the selection once Save starts.
    modal = open(); await modal.ready; delayed = true; await invalidate(); await gate();
    modal.contentEl.querySelector('[aria-label="Title"]').value = "Saved title during refresh";
    button(modal, "Save").click();
    check([...modal.contentEl.querySelectorAll("input,textarea,button")].every(control => control.disabled), "All original controls lock during Save");
    modal.close(); check(!modal.closed, "Close is prevented while saving");
